export class WebviewManager{constructor(webview){this.webview_=webview}setAccessToken(accessToken,shouldSendTokenToUrlFn){if(this.shouldSendTokenToUrlListener_){this.webview_.request.onBeforeSendHeaders.removeListener(this.shouldSendTokenToUrlListener_);this.shouldSendTokenToUrlListener_=null}this.shouldSendTokenToUrlListener_=details=>{if(shouldSendTokenToUrlFn(details.url)){details.requestHeaders.push({name:"Authorization",value:"Bearer "+accessToken})}return{requestHeaders:details.requestHeaders}};this.webview_.request.onBeforeSendHeaders.addListener(this.shouldSendTokenToUrlListener_,{urls:["<all_urls>"]},["blocking","requestHeaders"])}setAllowRequestFn(allowedRequestFn){if(this.allowedRequestListener_){this.webview_.request.onBeforeSendHeaders.removeListener(this.allowedRequestListener_);this.allowedRequestListener_=null}this.allowedRequestListener_=details=>({cancel:!allowedRequestFn(details.url)});this.webview_.request.onBeforeRequest.addListener(this.allowedRequestListener_,{urls:["<all_urls>"]},["blocking"])}}